// Give the remaining university entities the same hub shape using only the
// fields available in the verified directory extraction. Detailed admission
// articles are attached below only where the knowledge base has a dedicated
// long-form source.
const universityHubSource = "../Top 10 Universitas di Indonesia - Panduan Lengkap Kampus & Jurusan.md";
const admissionArticleByPath = {
  "university-universitas-gadjah-mada": { "Ujian Mandiri (UM) UGM": "um-ugm-cbt-2026" },
  "university-institut-teknologi-bandung": { "Seleksi Mandiri ITB (SM-ITB)": "ssu-itb-2026" },
  "university-institut-teknologi-sepuluh-nopember": { "Seleksi Kemitraan": "smits-ace-2026", "Seleksi Mandiri": "smits-ace-2026", "Seleksi Prestasi": "smits-ace-2026" },
  "university-universitas-airlangga": { "Seleksi Mandiri Universitas Airlangga (SMUA)": "smua-unair-2026" },
  "university-universitas-padjadjaran": { "Seleksi Masuk Universitas Padjadjaran (SMUP)": "smup-unpad-2026" },
  "university-institut-pertanian-bogor": { "Seleksi Masuk IPB (SM-IPB)": "sm-ipb-2026" },
  "university-universitas-brawijaya": { "Seleksi Mandiri (Selma)": "smub-ub-2026" }
};
const universityCatalogById = new Map(UNIVERSITY_CATALOG.map((catalog) => [catalog.universityId, catalog]));
KNOWLEDGE.filter((item) => item.entityType === "university" && item.id !== "university-universitas-indonesia").forEach((university) => {
  const catalog = universityCatalogById.get(university.id);
  if (catalog) {
    university.catalog = catalog.faculties;
    university.catalogUrl = catalog.catalogUrl;
    university.catalogSourcePeriod = catalog.sourcePeriod;
  }
  university.admissionDetails = (university.admissionPaths || []).map((name) => ({
    name,
    summary: "Nama jalur tercatat pada direktori PTN Unggul; rincian skema, syarat, jadwal, dan biaya perlu dicek pada sumber resmi.",
    year: "Ekstraksi 2026",
    status: "Ringkasan direktori · verifikasi ketentuan tahun berjalan",
    articleId: admissionArticleByPath[university.id]?.[name]
  }));
  university.sections = [
    { heading: "Profil institusi", table: [["Nama resmi", `${university.name} (${university.abbreviation})`], ["Jenis institusi", university.institutionType], ["Lokasi", university.location], ["Provinsi", university.province], ["Akreditasi institusi", university.accreditationInstitution], ["Jumlah prodi pada ekstraksi", `${university.majorCount} program studi`]] },
    { heading: "Jalur masuk yang tercatat", body: "Daftar berikut berasal dari ekstraksi direktori 23 Oktober 2026. Nama jalur dan periode pendaftaran tidak menggantikan pengumuman resmi universitas." },
    { heading: "Katalog program studi", body: `Ekstraksi direktori mencatat ${university.majorCount} program studi dalam ${university.catalog?.length || "sejumlah"} fakultas. Buka daftar fakultas di bawah untuk menelusuri prodi; gunakan website resmi universitas untuk katalog dan ketentuan terbaru.` },
    { heading: "Catatan verifikasi", body: "Data ini adalah ringkasan direktori. Verifikasi jalur yang dibuka, syarat, jadwal, biaya, UKT/IPI, dan daya tampung pada portal resmi sebelum digunakan dalam konsultasi." }
  ];
  university.sources = [
    { title: `Website resmi ${university.name}`, url: university.websiteUrl, kind: "Sumber resmi" },
    { title: "Direktori PTN Unggul — ekstraksi universitas", url: universityHubSource, kind: "Knowledge base lokal · ekstraksi 23 Oktober 2026" }
  ];
  university.ops = ["Buka website resmi universitas sebelum menjelaskan jadwal, syarat, biaya, atau status jalur.", "Gunakan listing ini sebagai orientasi awal; jangan menyebut data direktori sebagai jaminan peluang diterima."];
  university.metadata = { ...(university.metadata || {}), audience: "Student Advisor", topic: "Profil universitas dan jalur penerimaan", sourcePeriod: "Ekstraksi 23 Oktober 2026", status: "Katalog fakultas/prodi dari direktori; detail penerimaan dan kurikulum perlu verifikasi", note: "Akreditasi yang tercantum adalah akreditasi institusi, bukan akreditasi program studi." };
});

// Add non-UI program records from the same verified directory. Existing rich
// medical and UI records remain canonical; generated records fill the catalog
// hierarchy and carry an explicit data-gap marker when a full profile was not
// available in the extraction.
const existingStudyProgramIds = new Set(KNOWLEDGE.filter((item) => item.entityType === "study-program").map((item) => item.id));
KNOWLEDGE.push(...NON_UI_STUDY_PROGRAMS.filter((program) => !existingStudyProgramIds.has(program.id)));

